with ctx as (
  select u.id as user_id, m.organization_id
  from auth.users u
  join public.organization_memberships m on m.user_id=u.id and m.is_active=true and m.role='platform_admin'::public.app_role
  where lower(u.email)=lower('elba.rosalesc@gmail.com')
  order by m.organization_id limit 1
), items(resource_key,title,payload,quality_score) as (values
('premium-reading-4b-semillas','Comprensión lectora premium · La feria de las semillas','{"type":"reading-comprehension","premium":true,"subject":"Lenguaje y Comunicación","level":"4° básico","context":"Feria comunitaria de intercambio de semillas nativas","studentVersion":{"title":"Semillas que viajan","text":"En una feria comunitaria, familias de distintas localidades intercambian semillas de porotos, maíz y hierbas medicinales. Cada sobre lleva el nombre de la planta, el lugar donde creció y una recomendación para cuidarla. Martina descubre que algunas semillas necesitan más sol y otras prefieren suelo húmedo. Antes de elegir, conversa con una agricultora y compara la información de tres sobres. Finalmente escoge una variedad que puede crecer en el pequeño huerto de su escuela.","activities":["Localiza dos datos explícitos del texto.","Explica por qué Martina compara los sobres antes de elegir.","Infiere qué podría ocurrir si una semilla de suelo húmedo se planta en un lugar muy seco y justifica con evidencia.","Propón una pregunta que Martina podría hacer a la agricultora para tomar una mejor decisión."]},"teacherVersion":{"objective":"Comprender un texto informativo breve, localizar información, inferir y justificar con evidencia textual.","sequence":["Predicción con imagen","lectura modelada","subrayado de evidencia","respuesta individual o apoyada","metacognición qué-cómo-para qué"],"monitoring":["localiza información","relaciona causa y consecuencia","justifica con evidencia"]},"answerKey":["Familias intercambian semillas; cada sobre informa planta, origen y cuidados.","Porque las variedades tienen necesidades distintas y debe elegir una adecuada al huerto.","Podría crecer mal o secarse; se espera relación con la necesidad de humedad.","Respuesta pertinente relacionada con luz, riego, suelo o época de siembra."],"duaPie":{"visualSupport":true,"readAloud":true,"responseOptions":["escrita","oral","selección apoyada"],"chunkedInstructions":true},"accessibility":{"plainLanguage":true,"highContrastReady":true,"screenReaderReady":true,"reducedDistractors":true}}'::jsonb,97),
('premium-math-5b-pizzeria-fracciones','Matemática premium · La pizzería de las fracciones','{"type":"math-workshop","premium":true,"subject":"Matemática","level":"5° básico","context":"Pizzería escolar","studentVersion":{"scenario":"Cada pizza se divide en 8 porciones iguales. Un equipo vende 3/8 de una pizza, otro 4/8 y un tercero 6/8.","activities":["Representa 3/8 y 6/8 con un modelo visual.","Ordena 3/8, 4/8 y 6/8 de menor a mayor.","Calcula cuánto falta desde 6/8 para completar una pizza.","Dos cursos compran 3/8 y 4/8. ¿Qué fracción de una pizza compran en total?","Crea una combinación distinta que complete exactamente una pizza y explica cómo lo sabes."]},"teacherVersion":{"objective":"Representar, comparar y resolver situaciones de adición y complemento con fracciones de igual denominador, explicando estrategias.","materials":["círculos fraccionarios","tarjetas 1/8","recta numérica opcional"],"misconceptions":["sumar denominadores","comparar sólo numeradores sin considerar unidad"]},"answerKey":["Modelos con 3 y 6 partes sombreadas de 8.","3/8 < 4/8 < 6/8","2/8 o 1/4","7/8","Ejemplo 2/8+6/8=8/8; se aceptan otras combinaciones correctas."],"duaPie":{"concreteRepresentation":true,"multipleRepresentations":["objeto","dibujo","símbolo"],"stepByStep":true,"extendedTimeSuggested":true},"accessibility":{"largeManipulativesReady":true,"readAloudReady":true,"oneTaskPerBlock":true,"reducedVisualClutter":true}}'::jsonb,97),
('premium-science-4b-electricidad-segura','Ciencias premium · Misión electricidad segura','{"type":"science-mission","premium":true,"subject":"Ciencias Naturales","level":"4° básico","context":"Hogar y escuela segura","studentVersion":{"story":"El equipo de seguridad de la escuela debe revisar situaciones cotidianas antes de una feria científica.","missions":["Clasifica imágenes o descripciones en conductor/aislante.","Arma un circuito simple con pila, cables, interruptor y ampolleta usando un esquema.","Predice qué ocurre si el circuito queda abierto y explica por qué.","Detecta tres prácticas inseguras: manos mojadas, enchufe sobrecargado y cable pelado.","Diseña una regla de seguridad y explica a quién protege."]},"teacherVersion":{"objective":"Reconocer componentes de circuitos simples, diferenciar materiales conductores y aislantes y aplicar normas de seguridad.","materials":["pila","ampolleta de bajo voltaje","cables protegidos","tarjetas de situaciones"],"safety":"No manipular corriente domiciliaria; usar sólo material escolar de bajo voltaje."},"answerKey":{"conductors":["metal"],"insulators":["plástico","goma","madera seca"],"openCircuit":"La ampolleta no enciende porque el camino de la corriente está interrumpido.","safetyExamples":["secar manos","no sobrecargar enchufes","avisar por cables dañados"]},"duaPie":{"visualSequence":true,"roleCards":true,"alternativeResponse":true,"guidedPrediction":true},"accessibility":{"audioOptional":true,"symbolSupport":true,"keyboardReady":true,"plainLanguage":true}}'::jsonb,98),
('premium-calligraphy-1b-letras-movimiento','Caligrafía premium · Letras en movimiento','{"type":"calligraphy","premium":true,"subject":"Lenguaje / Caligrafía","level":"1° básico","context":"Taller progresivo de imprenta y manuscrita","studentVersion":{"stations":["Repasa trazos base: vertical, horizontal, inclinado, curva, arco y bucle.","Forma letras imprenta minúscula por familias de movimiento.","Forma letras manuscritas/cursivas con punto de inicio y flechas de direccionalidad.","Copia sílabas frecuentes manteniendo tamaño y separación.","Escribe palabras breves y una frase funcional: Mi nombre es ____."]},"teacherVersion":{"objective":"Desarrollar control grafomotor y legibilidad mediante progresión de trazos hacia letras imprenta y manuscrita, respetando ritmo individual.","progression":["trazo amplio","trazo guiado","letra aislada","sílabas","palabras","frase"],"observation":["postura funcional","prensión","direccionalidad","continuidad","tamaño relativo","espaciado"]},"answerKey":{"observation":"Se evalúa progreso funcional y legibilidad, no perfección estética ni velocidad."},"duaPie":{"thickTraceOption":true,"largerFormatOption":true,"handOverHandOptional":true,"sensoryBreaks":true},"accessibility":{"leftHandFriendly":true,"highContrastPaths":true,"reducedVisualClutter":true,"noTimeLimit":true}}'::jsonb,98),
('premium-graphomotor-prek-trazos-ciudad','Grafomotricidad premium · Viaje por la ciudad de los trazos','{"type":"graphomotor","premium":true,"subject":"Motricidad fina / Lenguaje","level":"Prekínder–Kínder","context":"Recorrido ilustrado por una ciudad amigable","studentVersion":{"missions":["Sube por edificios con trazos verticales.","Cruza calles con trazos horizontales.","Recorre techos y rampas con trazos inclinados.","Sigue parques con curvas, círculos y arcos.","Acompaña caracoles con espirales.","Cruza el río con ondas.","Sigue cercos en zigzag.","Decora guirnaldas con bucles.","Completa rutas combinadas sin levantar el lápiz cuando corresponda."]},"teacherVersion":{"objective":"Fortalecer coordinación visomotriz y direccionalidad mediante una progresión completa de trazos preescriturales.","progression":["vertical","horizontal","inclinado","curvo","circular","espiral","ondas","zigzag","bucles","arcos","combinaciones"],"guidance":"Modelar primero con movimiento corporal amplio, luego dedo, herramienta gruesa y finalmente lápiz."},"answerKey":{"observation":["control","continuidad","dirección","presión funcional","participación"]},"duaPie":{"multisensory":true,"thickPathOption":true,"largerFormat":true,"choiceOfTool":true},"accessibility":{"leftHandFriendly":true,"highContrastPaths":true,"reducedClutter":true,"movementBreaks":true}}'::jsonb,98),
('premium-inclusion-2b-rutina-instrucciones','PIE/DUA premium · Comprendo y sigo instrucciones','{"type":"inclusive-routine","premium":true,"subject":"Apoyo transversal","level":"1°–3° básico","context":"Rutina visual para aula","studentVersion":{"routine":["1. Miro o escucho la instrucción.","2. Identifico qué debo hacer.","3. Busco los materiales.","4. Hago un paso a la vez.","5. Reviso y pido ayuda si la necesito."],"practice":["Marca el verbo de acción en una instrucción breve.","Ordena tres pasos de una tarea cotidiana.","Elige qué material necesitas.","Explica con tus palabras qué harás primero."]},"teacherVersion":{"purpose":"Apoyo universal para comprensión de instrucciones sin reducir el objetivo curricular.","use":"Proyectar o imprimir; retirar gradualmente apoyos según autonomía.","monitoring":["identifica acción","inicia tarea","mantiene secuencia","revisa resultado","solicita ayuda funcional"]},"answerKey":{"criteria":["Reconoce acción principal","ordena secuencia lógica","selecciona material pertinente","expresa primer paso"]},"duaPie":{"visualSchedule":true,"oneStepAtATime":true,"modeling":true,"choiceOfResponse":true},"accessibility":{"pictogramReady":true,"plainLanguage":true,"readAloudReady":true,"largePrintReady":true}}'::jsonb,97),
('premium-history-5b-macrozonas-chile','Historia premium · Pasaporte por las macrozonas de Chile','{"type":"history-geography","premium":true,"subject":"Historia, Geografía y Ciencias Sociales","level":"5° básico","context":"Viaje geográfico por Chile","studentVersion":{"route":["Ubica Norte Grande, Norte Chico, Zona Central, Zona Sur y Zona Austral en un mapa.","Relaciona cada macrozona con un rasgo de clima o relieve.","Compara dos macrozonas usando una tabla de semejanzas y diferencias.","Lee un testimonio breve de una actividad productiva y deduce su zona probable.","Diseña una postal que combine paisaje, actividad humana y recomendación de cuidado ambiental."]},"teacherVersion":{"objective":"Ubicar y comparar macrozonas de Chile relacionando características naturales y actividades humanas.","materials":["mapa de Chile","tarjetas de paisaje","tabla comparativa"],"questions":["¿Qué evidencia del paisaje apoya tu decisión?","¿Cómo influye el territorio en una actividad humana?"]},"answerKey":{"zones":["Norte Grande","Norte Chico","Zona Central","Zona Sur","Zona Austral"],"rubric":["Ubicación correcta","relación geográfica pertinente","comparación con evidencia","comunicación clara"]},"duaPie":{"mapSimplification":true,"colorCoding":true,"oralResponse":true,"collaborativeRoles":true},"accessibility":{"audioDescriptionReady":true,"largeMapReady":true,"symbolSupport":true,"plainLanguage":true}}'::jsonb,97),
('premium-assessment-6b-fracciones-decimales','Evaluación premium adaptada · Fracciones y decimales','{"type":"assessment","premium":true,"subject":"Matemática","level":"6° básico","context":"Compras y medidas cotidianas","studentVersion":{"sections":[{"title":"Representa","items":["Representa 0,5 como fracción y 3/4 como decimal."]},{"title":"Compara","items":["Ordena 0,25; 1/2; 0,75 de menor a mayor."]},{"title":"Aplica","items":["Una botella contiene 1,5 L y se usan 3/4 L. ¿Cuánto queda?"]},{"title":"Explica","items":["Explica una estrategia para saber si 0,6 es mayor o menor que 1/2."]}]},"teacherVersion":{"purpose":"Evaluación formativa accesible con criterios visibles y posibilidad de respuesta apoyada.","criteria":["convierte representaciones","compara cantidades","resuelve contexto","explica estrategia"]},"answerKey":["0,5=1/2; 3/4=0,75","0,25 < 1/2 < 0,75","0,75 L","0,6 > 0,5=1/2; se aceptan estrategias equivalentes correctas."],"duaPie":{"visualModels":true,"extendedTimeSuggested":true,"alternativeResponse":["escrita","oral","manipulativa"],"reducedItemDensity":true},"accessibility":{"oneTaskPerBlock":true,"readAloudReady":true,"largePrintReady":true,"plainLanguage":true}}'::jsonb,97),
('premium-planlector-4b-misterio-biblioteca','Plan Lector premium · El misterio de la biblioteca','{"type":"reading-plan","premium":true,"subject":"Lenguaje y Comunicación","level":"4° básico","context":"Secuencia de lectura motivadora","studentVersion":{"before":["Observa portada y formula dos predicciones.","Activa vocabulario: pista, sospecha, evidencia, deducir."],"during":["Registra personaje, lugar, problema y una pista por tramo.","Marca una predicción que cambió y explica por qué."],"after":["Ordena cuatro eventos.","Elige la pista más importante y justifica.","Escribe un final alternativo coherente con personajes y conflicto."]},"teacherVersion":{"objective":"Sostener comprensión durante una lectura narrativa mediante predicción, monitoreo, inferencia y respuesta creativa.","sessions":4,"monitoring":["predice","actualiza hipótesis","localiza evidencia","infiere","produce respuesta coherente"]},"answerKey":{"rubric":["Comprensión global","uso de evidencia","coherencia","expresión personal pertinente"]},"duaPie":{"audioOption":true,"graphicOrganizer":true,"pairedReading":true,"responseChoice":true},"accessibility":{"dyslexiaFriendlyLayout":true,"readAloudReady":true,"plainLanguage":true,"chunkedTextReady":true}}'::jsonb,97),
('premium-writing-2b-descripcion-personaje','Escritura premium · Creo un personaje inolvidable','{"type":"writing-workshop","premium":true,"subject":"Lenguaje y Comunicación","level":"2°–3° básico","context":"Creación de personajes","studentVersion":{"steps":["Elige o imagina un personaje.","Completa una ficha: apariencia, gusto, habilidad y emoción frecuente.","Selecciona tres palabras precisas para describirlo.","Escribe 4 a 6 oraciones conectadas.","Revisa mayúscula inicial, punto final y que cada oración aporte información.","Comparte oralmente o lee tu descripción."],"sentenceStarters":["Mi personaje se llama...","Le gusta...","Cuando..., se siente...","Una habilidad especial es..."]},"teacherVersion":{"objective":"Planificar, escribir y revisar una descripción breve de personaje usando vocabulario pertinente y convenciones básicas.","feedback":"Retroalimentar primero contenido y claridad; luego convenciones seleccionadas.","rubric":["incluye rasgos pertinentes","organiza ideas","usa vocabulario descriptivo","revisa convenciones básicas"]},"answerKey":{"rubricLevels":["Logrado","En desarrollo","Requiere apoyo"]},"duaPie":{"oralPlanning":true,"wordBank":true,"visualOrganizer":true,"speechToTextCompatible":true},"accessibility":{"largeWritingSpace":true,"readAloudReady":true,"plainLanguage":true,"reducedCopying":true}}'::jsonb,97)
), run as (
  insert into public.resource_factory_runs (organization_id,triggered_by,status,requested_count,generated_count,published_count,started_at,completed_at)
  select organization_id,'system','completed',5,5,5,now(),now() from ctx returning id,organization_id
), resources as (
  insert into public.platform_resources (organization_id,created_by,resource_key,title,payload,created_at,updated_at)
  select c.organization_id,c.user_id,i.resource_key,i.title,i.payload,now(),now() from ctx c cross join items i
  on conflict (organization_id,resource_key) do update set title=excluded.title,payload=excluded.payload,updated_at=now()
  returning organization_id,resource_key,id
)
insert into public.resource_candidates (organization_id,factory_run_id,created_by,resource_key,title,payload,quality_score,quality_report,status,published_resource_id,model,usage,reviewed_at)
select c.organization_id,r.id,c.user_id,i.resource_key,i.title,i.payload,i.quality_score,'{"duaPie":true,"accessibility":true,"visualQuality":true,"studentVersion":true,"teacherVersion":true,"editableReusable":true,"answerKeyOrRubric":true,"curricularAlignment":true}'::jsonb,'published',p.id,'curated-premium-2026','{}'::jsonb,now()
from ctx c cross join items i cross join run r join resources p on p.organization_id=c.organization_id and p.resource_key=i.resource_key
on conflict (organization_id,resource_key) do update set title=excluded.title,payload=excluded.payload,quality_score=excluded.quality_score,quality_report=excluded.quality_report,status='published',published_resource_id=excluded.published_resource_id,reviewed_at=now();